algorithms.pseudocode:
Algorithm FindCertifiedPair(q):
  for g in GL₂(𝔽_q):
    if disc(charpoly(g)) is QNR mod q:
      for h in GL₂(𝔽_q):
        if gh ≠ hg and ⟨g,h⟩ = GL₂(𝔽_q):
          return (g, h)

Algorithm ComputeFamilywiseNorms(g, h, q):
  det_max = max_{χ≠1} |χ(det g) + χ(det g⁻¹) + χ(det h) + χ(det h⁻¹)| / 4
  ps_max = max_{χ₁≠χ₂} ‖M_{π(χ₁,χ₂)}(S)‖
  st_max = 2/√q  (Weil bound)
  cu_max = 2/(q-1)  (Deligne-Lusztig bound)
  return (det_max, ps_max, st_max, cu_max)
